import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import sys

route = sys.argv[1]
assert route in {"base", "base-r2", "candidate"}
root = Path.cwd()
app = root / ("fieldlog" if route != "candidate" else "fieldlog-candidate")
package = root / f"generated-{route}-host"
sdk = root / "android-mixer"
integration = Path("Integrations/GeneratedReport")
project_platform = Path("Platforms/Android")
target_sources = project_platform / "Sources/AppAndroid"
target_tests = project_platform / "Tests/AppAndroidTests"
app_tree = ("e39a5ea393076ca3f64b00648bf86f350ccf03dd" if route != "candidate"
            else "00406fe735a3e48b075dd545d8df77670caab336")
sdk_tree = "faf0902a82ffc7acb2ddde9c6dca24002f959c3d"

def git(repo, *args):
    return subprocess.check_output(["git", "-C", str(repo), *args])

def files(repo, tree, prefix):
    return [Path(name) for name in git(repo, "ls-tree", "-r", "--name-only", tree, "--", str(prefix)).decode().splitlines()]

def add(repo, tree, source, destination):
    if (package / destination).is_symlink():
        raise ValueError(f"Unexpected link {destination}")
    data = (package / destination).read_bytes()
    ref = f"{tree}:{source}"
    if data != git(repo, "cat-file", "blob", ref) or data != (repo / source).read_bytes():
        raise ValueError(f"Projection differs from {ref}: {destination}")
    manifest[str(destination)] = {
        "tree": tree, "path": str(source),
        "blob": git(repo, "rev-parse", ref).decode().strip(),
        "sha256": hashlib.sha256(data).hexdigest(),
    }

manifest = {}
for checkout, tree in [(app, app_tree), (sdk, sdk_tree)]:
    if git(checkout, "rev-parse", "HEAD^{tree}").decode().strip() != tree or git(checkout, "status", "--porcelain"):
        raise ValueError(f"Wrong tree or dirty source {checkout}")
for source, destination in [
    (project_platform / "ApplicationPackage.swift", Path("Package.swift")),
    (project_platform / "Package.swift", project_platform / "Package.swift"),
    (project_platform / "Package.resolved", project_platform / "Package.resolved"),
    *[(Path("Sources/FieldLogAndroid") / name, target_sources / name) for name in ["NativeEntry.swift", "PublicFactory.swift"]],
]:
    add(app, app_tree, integration / source, destination)

for module in ["FieldLogModels", "FieldLogStorage", "FieldLogFeatures"]:
    for source in files(app, app_tree, integration / "Sources" / module):
        add(app, app_tree, source, source.relative_to(integration))

tests = integration / "Tests/FieldLogAndroidTests"
for source in files(app, app_tree, tests):
    if source.suffix == ".swift" and source.parent == tests:
        add(app, app_tree, source, target_tests / source.name)

for source in files(sdk, sdk_tree, Path("sdk")):
    add(sdk, sdk_tree, source, Path("Generated/MixerSDK") / source.relative_to("sdk"))

source_groups = [target_sources, target_tests, Path("Generated/MixerSDK")]
source_groups += [Path("Sources") / module for module in ["FieldLogModels", "FieldLogStorage", "FieldLogFeatures"]]
for group in source_groups:
    observed = {str(path.relative_to(package)) for path in (package / group).rglob("*") if path.is_file()}
    expected = {path for path in manifest if Path(path).is_relative_to(group)}
    if observed != expected:
        raise ValueError(f"Unbound inputs in {group}: {observed ^ expected}")

for name in ["TreeBoundEntryPhotoTests.swift"] + (["CandidatePhotoProjectionTests.swift"] if route == "candidate" else []):
    destination = target_tests / name
    if (package / destination).exists():
        raise ValueError(f"Fixture destination exists: {destination}")
    shutil.copyfile(root / name, package / destination)
    manifest[str(destination)] = {"testFixture": name, "sha256": hashlib.sha256((package / destination).read_bytes()).hexdigest()}

projection_file = Path("Sources/FieldLogFeatures/EntryEditorPhotos.swift")
if (str(projection_file) in manifest) != (route == "candidate"):
    raise ValueError("Shared helper existence does not match the selected tree")
data = (json.dumps(manifest, sort_keys=True, separators=(",", ":")) + "\n").encode()
with (root / f"source-{route}.json").open("xb") as stream:
    stream.write(data)
print(f"sourceBound route={route} tree={app_tree} files={len(manifest)} sha256={hashlib.sha256(data).hexdigest()}")

