import hashlib
import json
from pathlib import Path
import shlex
import subprocess
import sys

route, phase = sys.argv[1:]
assert route in {"base", "base-r2", "candidate"} and phase in {"pre", "post"}
root = Path.cwd()
package = root / f"generated-{route}-host"
build = root / f"host-{route}" / "build"
provenance = (root / f"source-{route}.json").read_bytes()
manifest = json.loads(provenance)
artifacts = build / "out"
products = artifacts / "Products/Debug"
intermediates = artifacts / "Intermediates.noindex"
source_lists = sorted(intermediates.rglob("*.SwiftFileList"))
expected_modules = {"FieldLogAndroid", "FieldLogAndroidTests", "FieldLogFeatures", "FieldLogModels",
                    "FieldLogStorage", "MixerAndroid", "MixerCore", "MixerUI"}

def digest(data):
    return hashlib.sha256(data).hexdigest()

def sha(path):
    return digest(path.read_bytes())

def one_named(directory, name):
    matches = list(directory.rglob(name))
    if len(matches) != 1:
        raise ValueError((name, matches))
    return matches[0]

def record(path):
    return {"path": str(path.relative_to(root)), "sha256": sha(path), "bytes": path.stat().st_size}

for path, proof in manifest.items():
    if sha(package / path) != proof["sha256"]:
        raise ValueError(f"Input changed after binding: {path}")

modules = {source_list.name.removesuffix(".SwiftFileList") for source_list in source_lists}
if modules != expected_modules or len(source_lists) != len(modules):
    raise ValueError(f"Unexpected compiler source lists {modules}")
compiler = {}
for source_list in source_lists:
    module = source_list.name.removesuffix(".SwiftFileList")
    inputs = {}
    for name in shlex.split(source_list.read_text()):
        path = Path(name)
        if path.is_relative_to(package):
            relative = str(path.relative_to(package))
            proof = manifest[relative]
            inputs[relative] = proof["sha256"]
        elif path.is_relative_to(intermediates) and path.name == "test_entry_point.swift":
            inputs[str(path.relative_to(build))] = sha(path)
        else:
            raise ValueError(f"Unexpected compile input in {source_list}: {name}")
    compiler[module] = {"swiftFileList": record(source_list), "inputs": inputs}

factory_source = "Platforms/Android/Sources/AppAndroid/PublicFactory.swift"
projection_source = "Sources/FieldLogFeatures/EntryEditorPhotos.swift"
fixture_source = "Platforms/Android/Tests/AppAndroidTests/TreeBoundEntryPhotoTests.swift"
candidate_fixture_source = "Platforms/Android/Tests/AppAndroidTests/CandidatePhotoProjectionTests.swift"
candidate = route == "candidate"
if (factory_source not in compiler["FieldLogAndroid"]["inputs"]
        or fixture_source not in compiler["FieldLogAndroidTests"]["inputs"]
        or (projection_source in compiler["FieldLogFeatures"]["inputs"]) != candidate
        or (candidate_fixture_source in compiler["FieldLogAndroidTests"]["inputs"]) != candidate):
    raise ValueError("Route source lists do not prove expected product and test input membership")

linked = {}
for module in ["FieldLogAndroidTests", "FieldLogAndroid", "FieldLogFeatures"]:
    link_list = one_named(intermediates, module + ".LinkFileList")
    objects = [Path(name) for name in shlex.split(link_list.read_text())]
    if not all(obj.is_relative_to(artifacts) and obj.is_file() for obj in objects):
        raise ValueError(f"Unexpected link inputs for {module}")
    linked[module] = {"linkFileList": record(link_list), "objects": [record(obj) for obj in objects]}

for module, required in {
    "FieldLogAndroidTests": {"FieldLogAndroid.o", "FieldLogFeatures.o", "TreeBoundEntryPhotoTests.o"} | ({"CandidatePhotoProjectionTests.o"} if candidate else set()),
    "FieldLogAndroid": {"PublicFactory.o"},
    "FieldLogFeatures": {"EntryEditorPhotos.o"} if candidate else set(),
}.items():
    names = {Path(obj["path"]).name for obj in linked[module]["objects"]}
    if not required <= names or (not candidate and names & {"EntryEditorPhotos.o", "CandidatePhotoProjectionTests.o"}):
        raise ValueError(f"Wrong link inputs for {module}: {names}")

factory = one_named(intermediates, "PublicFactory.o")
symbols = subprocess.check_output(["/usr/bin/nm", "-u", str(factory)])
demangled = subprocess.check_output(["/usr/bin/xcrun", "swift-demangle"], input=symbols, text=False)
projection_symbols = [line.strip() for line in demangled.decode().splitlines() if "EntryEditorPhotos" in line]
if candidate:
    if not all(any(fragment in line for line in projection_symbols)
               for fragment in ["EntryEditorPhotos.init(ids:", "EntryEditorPhotos.canSelect.getter"]):
        raise ValueError(f"Candidate factory does not reference the shared projection: {projection_symbols}")
elif projection_symbols:
    raise ValueError(f"Baseline factory references the candidate projection: {projection_symbols}")

dependencies = {}
for name, pin, tree in [
    ("swift-crypto", "c2cbadd7263439d8015189668f96ff5b5be565ce", "841fdfd88fed694e6532a3200a91b0f85595c340"),
    ("swift-asn1", "3b6410f7dee09eb33cdd26260c5fd47fda19b0e2", "e7ed2e8c1483426c349b678e7d10940509f9d39c"),
]:
    checkout = build / "checkouts" / name
    def git(*args):
        return subprocess.check_output(["git", "-C", str(checkout), *args], text=True).strip()
    if git("rev-parse", "HEAD") != pin or git("rev-parse", "HEAD^{tree}") != tree or git("status", "--porcelain"):
        raise ValueError(f"Dependency checkout failed pin check: {name}")
    dependencies[name] = {"commit": pin, "tree": tree}

bundle = products / "FieldLogAndroidTests.xctest/Contents/MacOS/FieldLogAndroidTests"
if not bundle.is_file():
    raise ValueError(f"Missing compiled XCTest binary: {bundle}")

binding = {
    "sourceManifestSHA256": digest(provenance), "xctestExecutable": record(bundle),
    "compiledSources": compiler, "linkage": linked, "factoryProjectionSymbols": projection_symbols,
    "dependencies": dependencies,
}
data = (json.dumps(binding, sort_keys=True, separators=(",", ":")) + "\n").encode()
proof_path = root / f"compiled-{route}.json"
if phase == "pre":
    with proof_path.open("xb") as stream:
        stream.write(data)
elif proof_path.read_bytes() != data:
    raise ValueError("Build or source identity changed during test execution")
print(f"compiledBound route={route} phase={phase} sha256={digest(data)} xctestSHA256={sha(bundle)}")

