import CryptoKit
import Foundation
import MixerUI
import XCTest
@testable import FieldLogAndroid

private func digest(_ bytes: Data) -> String {
    SHA256.hash(data: bytes).map { String(format: "%02x", $0) }.joined()
}

private func refusal(_ label: String, _ action: () throws -> Void) throws -> String {
    do {
        try action()
    } catch {
        return "\(type(of: error)).\(error)"
    }
    throw ReviewError.failed("Unexpectedly accepted event: " + label)
}

@MainActor private func decodedDocument(_ surface: R109Surface) throws -> UIDocument {
    let frame = try XCTUnwrap(surface.frames.last)
    let packet = try XCTUnwrap(JSONSerialization.jsonObject(with: frame.packet) as? [String: Any])
    let document = try XCTUnwrap(packet["document"])
    return try UIDocument.decode(
        JSONSerialization.data(withJSONObject: document),
        validator: UIValidator(supportedTextFieldAxes: surface.profile.capabilities.textFieldAxes,
                               textValuePolicy: surface.profile.textValuePolicy)
    )
}

final class TreeBoundEntryPhotoTests: XCTestCase {
    @MainActor func testDraftPhotosAndRefusalsAcrossColdReopen() async throws {
        let environment = ProcessInfo.processInfo.environment
        let tree = try XCTUnwrap(environment["FIELDLOG_SOURCE_TREE"])
        let dir = URL(fileURLWithPath: try XCTUnwrap(environment["FIELDLOG_WORKSPACE"]))
            .appendingPathComponent("tree-bound-entry-photos")
        try check(!FileManager.default.fileExists(atPath: dir.path), "expected a fresh disk workspace")
        let surface = R109Surface()
        let app = try await open(dir, surface)
        let owner = try XCTUnwrap(app.host.owner)
        let title = "Inspection 🧪"
        let note = "Cafe\u{301}\n東京\nLast line\n"
        let finalNote = note + "Rechecked 👩🏽‍🔬\n"
        let date = "2024-02-29T00:00:00.125Z"
        try send(app, "workspace.entries")
        try send(app, "entry-title", .textChange, .string(title))
        try send(app, "entry-note", .textChange, .string(note))
        try send(app, "entry-date", .textChange, .string(date))
        try send(app, "entry.category.issue")
        try send(app, "entry.saveDraft")
        try await app.settle()
        let draftID = try XCTUnwrap(app.presentation.entryState?.draft.id)
        let stored = try XCTUnwrap(disk(dir).drafts.first)
        try check(stored.id == draftID && stored.note.utf8.elementsEqual(note.utf8), "initial save")
        print("PHOTO_HOST tree=\(tree) stage=save draft=\(draftID) noteUTF8Base64=\(Data(stored.note.utf8).base64EncodedString()) dateEpoch=\(stored.occurredAt.timeIntervalSince1970) category=\(stored.category.rawValue)")

        var photoBytes: [Data] = []
        var pickerAtSeven: UIEventEnvelope?
        for count in 0...8 {
            let document = try decodedDocument(surface)
            let roster = try XCTUnwrap(fieldLogNode("entry.attachments", in: document.root)?.properties["text"]?.string)
            let picker = try XCTUnwrap(fieldLogNode("entry-photo-select", in: document.root))
            let disabled = picker.properties["disabled"]?.bool == true
            try check(roster == "Attachments: \(count) · References preserved" && disabled == (count == 8), "decoded roster and picker at \(count)")
            if count >= 7 {
                print("PHOTO_HOST tree=\(tree) stage=decoded-frame revision=\(document.revision) roster=\(roster) pickerDisabled=\(disabled)")
            }
            if count == 8 { break }

            if count == 7 { pickerAtSeven = try event(app, "entry-photo-select") }
            try send(app, "entry-photo-select")
            let request = try XCTUnwrap(app.presentation.takePhotoRequest())
            try check(request.draftID == draftID, "request binds the selected draft")
            let jpeg = Data([0xff, 0xd8, 0xff, 0xef, 0, 3, UInt8(count), 0xff, 0xd9])
            photoBytes.append(jpeg)
            let accepted = await app.presentation.completePhoto(requestID: request.id, result: .jpeg(jpeg))
            try check(accepted, "photo completion \(count + 1)")
            try await app.settle()
        }

        let before = try Data(contentsOf: file(dir))
        let beforePhotos = try disk(dir).attachments
        let staleBytes = try JSONEncoder().encode(XCTUnwrap(pickerAtSeven))
        let stale = try refusal("stale picker envelope") { try app.send(owner: owner, originalEnvelope: staleBytes) }
        let ninth = try refusal("current ninth-photo request") { try send(app, "entry-photo-select") }
        let wrongValue = try refusal("wrong note value type") {
            try send(app, "entry-note", .textChange, .bool(true))
        }
        try check(Data(contentsOf: file(dir)) == before, "immediate refusals leave workspace bytes unchanged")
        let invalidNote = "invalid\u{0}note"
        try send(app, "entry-note", .textChange, .string(invalidNote))
        try send(app, "entry.saveDraft")
        try await app.settle()
        let invalid = try XCTUnwrap(app.presentation.entryState?.failure)
        try check(app.presentation.entryState?.draft.note == invalidNote, "save refusal keeps the edit in memory")
        try check(app.presentation.takePhotoRequest() == nil, "no refused event opens a picker")
        try check(Data(contentsOf: file(dir)) == before, "refused input leaves workspace bytes unchanged")
        let photoDirectory = dir.appendingPathComponent("FieldLog/photos")
        try check(Set(FileManager.default.contentsOfDirectory(atPath: photoDirectory.path)) == Set(beforePhotos.map(\.filename)), "refused events leave the photo file roster unchanged")
        print("PHOTO_HOST tree=\(tree) stage=refusals stale=\(stale) ninth=\(ninth) wrongValue=\(wrongValue) invalidNoteSave=\(invalid) diskSHA256=\(digest(before)) pickerRequest=nil")

        let draftWithPhotos = try XCTUnwrap(disk(dir).drafts.first)
        try check(draftWithPhotos.attachmentIDs.count == 8, "eight durable photo references")
        try check(Set(draftWithPhotos.attachmentIDs).count == 8, "unique references")
        try send(app, "entry-note", .textChange, .string(finalNote))
        try send(app, "entry.saveDraft")
        try check(app.presentation.entryState?.saving == true, "close starts while the save is pending")
        await app.close()
        try check(app.host.owner == nil && surface.owner == nil, "close revoked both owners")
        let closed = try XCTUnwrap(disk(dir).drafts.first)
        try check(closed.note.utf8.elementsEqual(finalNote.utf8) && closed.attachmentIDs == draftWithPhotos.attachmentIDs, "close drains edited draft with the same ordered references")
        let finalDisk = try Data(contentsOf: file(dir))
        print("PHOTO_HOST tree=\(tree) stage=close ownerRevoked=true pendingSaveDrained=true diskSHA256=\(digest(finalDisk))")

        let coldSurface = R109Surface()
        let cold = try await open(dir, coldSurface)
        let freshOwner = try XCTUnwrap(cold.host.owner)
        let reopened = try XCTUnwrap(cold.presentation.entryState?.draft)
        try check(freshOwner != owner && reopened.id == draftID && reopened.projectID == stored.projectID, "fresh owner restores the same draft")
        try check(reopened.title.utf8.elementsEqual(title.utf8) && reopened.note.utf8.elementsEqual(finalNote.utf8), "exact reopened text bytes")
        try check(reopened.category == .issue && reopened.occurredAt == Date(timeIntervalSince1970: 1709164800.125), "exact reopened category and date")
        try check(reopened.attachmentIDs == closed.attachmentIDs, "ordered references survive cold reopen")
        let reopenedDocument = try decodedDocument(coldSurface)
        let reopenedRoster = try XCTUnwrap(fieldLogNode("entry.attachments", in: reopenedDocument.root)?.properties["text"]?.string)
        let reopenedPicker = try XCTUnwrap(fieldLogNode("entry-photo-select", in: reopenedDocument.root)?.properties["disabled"]?.bool)
        try check(reopenedRoster == "Attachments: 8 · References preserved" && reopenedPicker, "cold frame keeps the picker disabled")
        let foreign = try refusal("old owner") { try cold.send(owner: owner, originalEnvelope: staleBytes) }
        var hashes: [String] = []
        for (index, id) in reopened.attachmentIDs.enumerated() {
            let attachment = try XCTUnwrap(cold.presentation.workspace.attachments.first { $0.id == id })
            let bytes = try Data(contentsOf: photoDirectory.appendingPathComponent(attachment.filename))
            try check(bytes == photoBytes[index], "ordered exact bytes for photo \(index + 1)")
            hashes.append(digest(bytes))
        }
        try check(Data(contentsOf: file(dir)) == finalDisk, "cold read and old-owner refusal leave disk bytes unchanged")
        await cold.close()
        print("PHOTO_HOST tree=\(tree) stage=cold-reopen draft=\(reopened.id) title=\(reopened.title) noteUTF8Base64=\(Data(reopened.note.utf8).base64EncodedString()) dateEpoch=\(reopened.occurredAt.timeIntervalSince1970) category=\(reopened.category.rawValue) roster=\(reopenedRoster) pickerDisabled=\(reopenedPicker) oldOwner=\(foreign) orderedIDs=\(reopened.attachmentIDs.map(\.uuidString).joined(separator: ",")) orderedPhotoSHA256=\(hashes.joined(separator: ","))")
    }
}

