import FieldLogFeatures
import Foundation
import XCTest

final class CandidatePhotoProjectionTests: XCTestCase {
    func testSharedProjectionPreservesOrderAndAppliesEightPhotoLimit() throws {
        let ids = try (1...9).reversed().map { index in
            try XCTUnwrap(UUID(uuidString: "00000000-0000-0000-0000-00000000000\(index)"))
        }
        XCTAssertEqual(EntryEditorPhotos.limit, 8)
        let counts = [0, 7, 8, 9]
        let projections = counts.map { EntryEditorPhotos(ids: Array(ids.prefix($0))) }
        for (count, projection) in zip(counts, projections) {
            XCTAssertEqual(projection.ids, Array(ids.prefix(count)))
        }
        XCTAssertEqual(projections.map(\.canSelect), [true, true, false, false])
        print("PHOTO_PROJECTION limit=\(EntryEditorPhotos.limit) counts=\(counts) canSelect=\(projections.map(\.canSelect)) order=preserved")
    }
}
